  67: function componentDefinition(source) {
  68:   const match = source.match(/<script>([\s\S]*?)<\/script>/);
  69:   assert(match, 'component script block is required');
  70:   const executable = match[1].replace(/export\s+default\s+/, 'return ');
  71:   return Function(executable)();
  72: }
