  74: function templateSource(source) {
  75:   const match = source.match(/<template>([\s\S]*?)<\/template>/);
  76:   assert(match, 'component template block is required');
  77:   return match[1];
  78: }
  79: 
  80: function attributesForTag(template, tag) {
  81:   const match = template.match(new RegExp(`<${tag}\\s+([\\s\\S]*?)>`));
  82:   assert(match, `${tag} mount is required`);
  83:   const attributes = {};
  84:   const pattern = /([\w-]+)\s*=\s*"([^"]*)"/g;
  85:   let attribute;
  86:   while ((attribute = pattern.exec(match[1])) !== null) {
  87:     attributes[attribute[1]] = attribute[2];
  88:   }
  89:   return attributes;
  90: }
  91: 
  92: function attributesForClass(template, className) {
  93:   const tags = template.match(/<[\w-]+\s+[\s\S]*?>/g) || [];
  94:   const tag = tags.find((candidate) => new RegExp(`class="[^"]*\\b${className}\\b`).test(candidate));
  95:   assert(tag, `${className} element is required`);
  96:   return attributesForTag(tag, tag.match(/^<([\w-]+)/)[1]);
  97: }
