 103: function templateBindings(template) {
 104:   const bindings = new Set();
 105:   const tagPattern = /<[\w-]+\s+([^>]+)>/g;
 106:   let tag;
 107:   while ((tag = tagPattern.exec(template)) !== null) {
 108:     const attributePattern = /[\w-]+\s*=\s*"([^"]*)"/g;
 109:     let attribute;
 110:     while ((attribute = attributePattern.exec(tag[1])) !== null) {
 111:       const bindingPattern = /\{\{\s*([A-Za-z_$][\w$]*)\s*\}\}/g;
 112:       let binding;
 113:       while ((binding = bindingPattern.exec(attribute[1])) !== null) bindings.add(binding[1]);
 114:     }
 115:   }
 116:   return bindings;
 117: }
