 128:       .map((declaration) => declaration.trim())
 129:       .filter(Boolean)
 130:       .map((declaration) => {
 131:         const separator = declaration.indexOf(':');
 132:         return [declaration.slice(0, separator).trim(), declaration.slice(separator + 1).trim()];
 133:       }),
 134:   );
